'use strict';

/**
* LAPACK routine to generate an `M-by-N` real matrix `Q` with orthonormal columns, which is defined as the first `N` columns of a product of `K` elementary reflectors of order `M`.
*
* @module @stdlib/lapack/base/dorgbr
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var dorgbr = require( '@stdlib/lapack/base/dorgbr' );
*
* var A = new Float64Array( [ 1, 0, 0, 0, 1, 0 ] );
* var TAU = new Float64Array( [ 2, 2 ] );
* var WORK = new Float64Array( 10 );
*
* var info = dorgbr( 'column-major', 3, 2, 2, A, 3, TAU, WORK, 10 );
* // A => <Float64Array>[ -1, 0, 0, 0, -1, 0 ]
* // info => 0
* // WORK[ 0 ] => 2
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dorgbr;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dorgbr = main;
} else {
	dorgbr = tmp;
}


// EXPORTS //

module.exports = dorgbr;

// exports: { "ndarray": "dorgbr.ndarray" }
